/**
 * Short revision notes, one file per topic under data/notes, loaded on demand like the question
 * bank (data/notes/index.ts is generated by `npm run bank:index`).
 */
export interface TopicNotes {
  sections: { heading: string; points: string[] }[];
  /** Formulas, rules or must-remember facts, one per line. */
  formulas?: string[];
  /** Common mistakes and how to avoid them. */
  traps?: string[];
  /** How exams ask this topic. */
  examTips?: string[];
}
